-- C05 + Q01 apply. WRITES. Generated by build-and-rehearse.py from (keep in sync):
--   supabase/migrations/20261028180000_q01_new_customer_quest.sql
--   supabase/migrations/20261028181000_c05_campaign_codes.sql
-- Idempotent: re-running is harmless. Run preflight.sql first and readback.sql after.
begin;
-- Q01: staff quest "customer baru" (supersedes draft #197 / 20261025111000).
--
-- Business rules (docs/reports/2026-10-28-keputusan-default.md, Q01):
--   * the cashier who closes a customer's FIRST paid POS receipt claims that customer once;
--   * Rp0 receipts never claim (total minus merchant fee must be > 0);
--   * a customer card created before the quest period (day/month of the sale, WIB) is not new,
--     nor is a card created before the quest itself was set up (protects against bulk imports);
--   * a duplicate card with the same phone as an older card is not new;
--   * a card created by the bulk customer import (customers.imported_at) is not new;
--   * an earlier paid clinic invoice (same card or phone) means the customer is not new;
--   * a full return without void keeps the claim; a void (cancel_posted_sale) releases it and
--     the existing staff-effect reversal removes the quest progress, as for every other quest.
--
-- Design: the claim is decided inside the payment finalizer transaction by a trigger on
-- sales.payments_finalized_at, so two concurrent receipts can never both claim the same
-- customer and no queue/worker/service-role path is needed. Quest progress keeps using the
-- existing apply_sale_staff_effects call; it only reads the claim row.

alter table public.staff_quest_definitions
  drop constraint if exists staff_quest_definitions_target_kind_check;
alter table public.staff_quest_definitions
  add constraint staff_quest_definitions_target_kind_check
  check (target_kind in ('product_qty','category_qty','total_sales_amount','new_customer'));
alter table public.staff_quest_definitions
  drop constraint if exists staff_quest_new_customer_count_check;
alter table public.staff_quest_definitions
  add constraint staff_quest_new_customer_count_check
  check (target_kind <> 'new_customer'
    or (target_value >= 1 and target_value = trunc(target_value) and target_ref_id is null));

-- One global identity per phone: "0812-xxx", "+62812xxx" and "62812xxx" are the same person.
create or replace function public.quest_customer_phone_key(p_phone text) returns text
language plpgsql immutable strict set search_path = '' as $$
declare digits text := regexp_replace(p_phone, '[^0-9]', '', 'g');
begin
  if left(digits, 2) = '62' and length(digits) > 9 then digits := '0' || substr(digits, 3); end if;
  -- Placeholder numbers (too short, or one repeated digit) never identify anyone.
  if length(digits) < 8 or length(replace(digits, left(digits, 1), '')) = 0 then return null; end if;
  return digits;
end $$;
revoke all on function public.quest_customer_phone_key(text) from public, anon, authenticated, service_role;
-- Expression-index maintenance runs as the customer writer; this pure formatter needs EXECUTE.
grant execute on function public.quest_customer_phone_key(text) to authenticated, service_role;
create index if not exists customers_quest_phone_key_idx
  on public.customers (public.quest_customer_phone_key(phone));

-- Cards created by the bulk import (Pengaturan > Impor) are existing customers, never "new".
alter table public.customers add column if not exists imported_at timestamptz;
comment on column public.customers.imported_at is
  'Q01: set by the bulk customer import; such cards never count as a new customer. Immutable once set.';
create or replace function public.guard_customer_imported_at() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if old.imported_at is not null and new.imported_at is distinct from old.imported_at then
    raise exception 'Penanda impor pelanggan tidak boleh diubah' using errcode = '42501';
  end if;
  return new;
end $$;
revoke all on function public.guard_customer_imported_at() from public, anon, authenticated, service_role;
drop trigger if exists q01_customer_imported_at on public.customers;
create trigger q01_customer_imported_at before update of imported_at on public.customers
  for each row execute function public.guard_customer_imported_at();

create table if not exists public.quest_new_customer_claims (
  customer_id uuid primary key references public.customers(id) on delete cascade,
  sale_id uuid not null unique references public.sales(id) on delete cascade,
  staff_id uuid not null references public.profiles(id),
  branch_id uuid not null references public.branches(id),
  phone_key text,
  claimed_at timestamptz not null default now()
);
create index if not exists quest_new_customer_claims_phone_idx
  on public.quest_new_customer_claims (phone_key) where phone_key is not null;
alter table public.quest_new_customer_claims enable row level security;
revoke all on public.quest_new_customer_claims from public, anon, authenticated, service_role;
comment on table public.quest_new_customer_claims is
  'Q01: one row per customer acquired by a cashier. Written only by the payment finalizer trigger; removed when that sale is voided.';

create or replace function public.quest_claim_new_customer() returns trigger
language plpgsql security definer set search_path = '' as $$
declare v_phone text; v_created timestamptz; v_imported timestamptz;
begin
  if old.payments_finalized_at is not null or new.payments_finalized_at is null
     or new.channel is not null or not new.quest_effects_tracked
     or new.customer_id is null or new.cashier_id is null or new.voided_at is not null
     or coalesce(new.total, 0) - coalesce(new.merchant_fee_total, 0) <= 0 then
    return null;                                   -- Rp0 receipts never claim
  end if;
  select public.quest_customer_phone_key(c.phone), c.created_at, c.imported_at into v_phone, v_created, v_imported
    from public.customers c where c.id = new.customer_id;
  if not found or v_imported is not null then return null; end if;   -- imported cards are not new
  -- Serialize all claims for one identity (card or phone) inside this transaction.
  perform pg_advisory_xact_lock(hashtextextended('vetos:q01:' || coalesce(v_phone, new.customer_id::text), 0));
  if exists (select 1 from public.quest_new_customer_claims c
             where c.customer_id = new.customer_id or (v_phone is not null and c.phone_key = v_phone)) then
    return null;
  end if;
  -- A newer card for a phone that already has an older card is a duplicate, not a new customer.
  if v_phone is not null and exists (
       select 1 from public.customers o
       where o.id <> new.customer_id and public.quest_customer_phone_key(o.phone) = v_phone
         and (o.created_at, o.id) < (v_created, new.customer_id)) then
    return null;
  end if;
  -- Any earlier paid, non-void, non-zero receipt for this identity means the customer is not new.
  -- Legacy rows (quest_effects_tracked=false) predate payment finalization and count as paid.
  if exists (
       select 1 from public.sales p
       join public.customers o on o.id = p.customer_id
       where p.id <> new.id and p.voided_at is null
         and (p.payments_finalized_at is not null or not p.quest_effects_tracked)
         and coalesce(p.total, 0) - coalesce(p.merchant_fee_total, 0) > 0
         and (o.id = new.customer_id or (v_phone is not null and public.quest_customer_phone_key(o.phone) = v_phone))) then
    return null;
  end if;
  -- A paid (Lunas/DP), non-void, non-zero clinic invoice for this identity also means not new.
  if exists (
       select 1 from public.invoices i
       join public.visits vi on vi.id = i.visit_id
       join public.customers o on o.id = vi.customer_id
       where i.voided_at is null and i.paid_status in ('Lunas', 'DP') and coalesce(i.total, 0) > 0
         and (o.id = new.customer_id or (v_phone is not null and public.quest_customer_phone_key(o.phone) = v_phone))) then
    return null;
  end if;
  insert into public.quest_new_customer_claims (customer_id, sale_id, staff_id, branch_id, phone_key, claimed_at)
  values (new.customer_id, new.id, new.cashier_id, new.branch_id, v_phone, new.payments_finalized_at)
  on conflict do nothing;
  return null;
end $$;
revoke all on function public.quest_claim_new_customer() from public, anon, authenticated, service_role;
drop trigger if exists q01_claim_new_customer on public.sales;
create trigger q01_claim_new_customer after update of payments_finalized_at on public.sales
  for each row execute function public.quest_claim_new_customer();

-- Void releases the claim; a return (no void) leaves it untouched.
create or replace function public.quest_release_new_customer() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if old.voided_at is null and new.voided_at is not null then
    delete from public.quest_new_customer_claims where sale_id = new.id;
  end if;
  return null;
end $$;
revoke all on function public.quest_release_new_customer() from public, anon, authenticated, service_role;
drop trigger if exists q01_release_new_customer on public.sales;
create trigger q01_release_new_customer after update of voided_at on public.sales
  for each row execute function public.quest_release_new_customer();

-- Quest progress: a 'new_customer' quest gains 1 when this sale holds a claim whose customer
-- card was created in the same quest period (daily = WIB date, monthly = WIB month) and not
-- before the quest definition existed.
-- Anchored, counted patch of the existing effect function (same pattern as K02/K10);
-- every other quest kind, the snapshot and the reversal contract stay byte-identical.
do $patch$
declare
  signature regprocedure := 'public.apply_sale_staff_effects(uuid)'::regprocedure;
  definition text := pg_get_functiondef(signature);
  old_text text := E'  if q.target_kind=''total_sales_amount'' then amount:=s.total-coalesce(s.merchant_fee_total,0);';
  new_text text := E'  if q.target_kind=''new_customer'' then\n'
    || E'   select count(*) into amount from public.quest_new_customer_claims nc join public.customers nc_c on nc_c.id=nc.customer_id\n'
    || E'    where nc.sale_id=s.id and nc_c.created_at>=q.created_at and to_char(nc_c.created_at at time zone ''Asia/Jakarta'',case when q.quest_type=''daily'' then ''YYYY-MM-DD'' else ''YYYY-MM'' end)\n'
    || E'     =to_char(d,case when q.quest_type=''daily'' then ''YYYY-MM-DD'' else ''YYYY-MM'' end);\n'
    || E'  elsif q.target_kind=''total_sales_amount'' then amount:=s.total-coalesce(s.merchant_fee_total,0);';
begin
  if position('quest_new_customer_claims' in definition) > 0 then
    return;                                        -- already applied (idempotent re-run)
  end if;
  if (length(definition) - length(replace(definition, old_text, ''))) / length(old_text) <> 1 then
    raise exception 'Q01_QUEST_FUNCTION_DRIFT: apply_sale_staff_effects changed; review before release';
  end if;
  execute replace(definition, old_text, new_text);
end
$patch$;

-- C05: kode promo/kampanye (supersedes drafts #225, #228, #236).
--
-- Business rules (docs/reports/2026-10-28-keputusan-default.md, C05):
--   * a campaign code is bound to exactly one existing voucher OR promo;
--   * optional usage cap per code (NULL = unlimited);
--   * only active OWNER/ADMIN create or change codes.
--
-- One code field at checkout: the cashier types the campaign code where a voucher code goes.
-- Voucher-bound: the bound voucher's own rules and formula apply unchanged.
-- Promo-bound: that promo is applied to this transaction (also when it is not "potong otomatis").
-- Usage = paid (finalized) non-void POS receipts + posted non-void clinic invoices that carry
-- the code; an unfinished receipt left by a crashed checkout does not use the code. The cap is
-- checked when the document is written (early refusal) and again, authoritatively, when a POS
-- receipt is finalized. Both checks lock the code row before counting, so concurrent checkouts
-- are serialized and can never exceed it. A void frees the use; a clinic reissue keeps the
-- original use (it is never counted twice).

create table if not exists public.campaign_codes (
  id uuid primary key default gen_random_uuid(),
  code varchar(24) not null unique
    constraint campaign_codes_code_format check (code ~ '^[A-Z0-9_-]{3,24}$'),
  voucher_id uuid references public.vouchers(id) on delete cascade,
  promo_id uuid references public.promos(id) on delete cascade,
  max_uses integer constraint campaign_codes_max_uses_positive check (max_uses is null or max_uses > 0),
  is_active boolean not null default true,
  note text constraint campaign_codes_note_length check (note is null or length(note) <= 200),
  created_by uuid references public.profiles(id) on delete set null default auth.uid(),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint campaign_codes_one_target check ((voucher_id is null) <> (promo_id is null))
);
comment on table public.campaign_codes is
  'C05 campaign code: alias for one existing voucher or promo, optional usage cap. Usage is counted from sales/invoices.campaign_code.';

alter table public.campaign_codes enable row level security;
revoke all on public.campaign_codes from public, anon;
grant select, insert, update, delete on public.campaign_codes to authenticated;
-- Cashiers must resolve codes at checkout, like vouchers (readable by every signed-in user).
drop policy if exists campaign_codes_read on public.campaign_codes;
create policy campaign_codes_read on public.campaign_codes for select to authenticated using (true);
drop policy if exists campaign_codes_manager_insert on public.campaign_codes;
create policy campaign_codes_manager_insert on public.campaign_codes for insert to authenticated
  with check (exists (select 1 from public.profiles p where p.id = (select auth.uid())
    and p.is_active and p.role in ('OWNER','ADMIN')));
drop policy if exists campaign_codes_manager_update on public.campaign_codes;
create policy campaign_codes_manager_update on public.campaign_codes for update to authenticated
  using (exists (select 1 from public.profiles p where p.id = (select auth.uid())
    and p.is_active and p.role in ('OWNER','ADMIN')))
  with check (exists (select 1 from public.profiles p where p.id = (select auth.uid())
    and p.is_active and p.role in ('OWNER','ADMIN')));
drop policy if exists campaign_codes_manager_delete on public.campaign_codes;
create policy campaign_codes_manager_delete on public.campaign_codes for delete to authenticated
  using (exists (select 1 from public.profiles p where p.id = (select auth.uid())
    and p.is_active and p.role in ('OWNER','ADMIN')));

-- A campaign code must never also be a voucher code (either direction, any write path).
create or replace function public.guard_campaign_code_collision() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  perform pg_advisory_xact_lock(hashtextextended('vetos:c05-code:' || upper(new.code), 0));
  if tg_table_name = 'campaign_codes' then
    if exists (select 1 from public.vouchers v where upper(v.code) = upper(new.code)) then
      raise exception 'KODE_KAMPANYE: Kode % sudah dipakai sebagai kode voucher', new.code using errcode = '23505';
    end if;
  elsif exists (select 1 from public.campaign_codes c where c.code = upper(new.code)) then
    raise exception 'KODE_KAMPANYE: Kode % sudah dipakai sebagai kode kampanye', new.code using errcode = '23505';
  end if;
  return new;
end $$;
revoke all on function public.guard_campaign_code_collision() from public, anon, authenticated, service_role;
drop trigger if exists c05_campaign_code_collision on public.campaign_codes;
create trigger c05_campaign_code_collision before insert or update of code on public.campaign_codes
  for each row execute function public.guard_campaign_code_collision();
drop trigger if exists c05_voucher_code_collision on public.vouchers;
create trigger c05_voucher_code_collision before insert or update of code on public.vouchers
  for each row execute function public.guard_campaign_code_collision();

-- Snapshot of the typed campaign code on each document; voucher_code stays the real voucher.
alter table public.sales add column if not exists campaign_code varchar(24);
alter table public.invoices add column if not exists campaign_code varchar(24);
create index if not exists sales_campaign_code_idx on public.sales (campaign_code) where campaign_code is not null;
create index if not exists invoices_campaign_code_idx on public.invoices (campaign_code) where campaign_code is not null;

-- One definition of "a use": finalized non-void receipts + posted non-void invoices.
create or replace function public.campaign_code_used(p_code text) returns bigint
language sql stable security definer set search_path = '' as $$
  select (select count(*) from public.sales s where s.campaign_code = p_code
            and s.voided_at is null and s.payments_finalized_at is not null)
       + (select count(*) from public.invoices i where i.campaign_code = p_code and i.voided_at is null)
$$;
revoke all on function public.campaign_code_used(text) from public, anon, authenticated, service_role;

create or replace function public.guard_campaign_code_use() returns trigger
language plpgsql security definer set search_path = '' as $$
declare k public.campaign_codes%rowtype; v_voucher text; v_used bigint; src_id uuid; src_code text; src_voucher text;
begin
  if tg_op = 'UPDATE' then
    if new.campaign_code is distinct from old.campaign_code then
      raise exception 'KODE_KAMPANYE: Kode kampanye pada dokumen tidak boleh diubah' using errcode = '23514';
    end if;
    if new.campaign_code is not null and new.voucher_code is distinct from old.voucher_code then
      raise exception 'KODE_KAMPANYE: Voucher dari kode kampanye tidak boleh diubah' using errcode = '23514';
    end if;
    return new;
  end if;

  -- Clinic void+reissue: the new invoice inherits the original code and its single use.
  if tg_table_name = 'invoices' then
    src_id := (to_jsonb(new) ->> 'reissued_from')::uuid;   -- sales rows have no such column
  end if;
  if src_id is not null then
    select i.campaign_code, i.voucher_code into src_code, src_voucher
      from public.invoices i where i.id = src_id;
    if new.campaign_code is null then new.campaign_code := src_code; end if;
    if new.campaign_code is distinct from src_code then
      raise exception 'KODE_KAMPANYE: Penerbitan ulang tidak boleh mengganti kode kampanye' using errcode = '23514';
    end if;
    if src_code is not null and new.voucher_code is distinct from src_voucher then
      raise exception 'KODE_KAMPANYE: Voucher dari kode kampanye tidak boleh diubah' using errcode = '23514';
    end if;
    return new;
  end if;

  if new.campaign_code is null then return new; end if;

  -- Row lock serializes every checkout of this code until its transaction ends.
  select * into k from public.campaign_codes c where c.code = new.campaign_code for update;
  if not found then
    raise exception 'KODE_KAMPANYE: Kode % tidak ditemukan', new.campaign_code using errcode = 'P0001';
  end if;
  if not k.is_active then
    raise exception 'KODE_KAMPANYE: Kode % sedang dinonaktifkan', k.code using errcode = 'P0001';
  end if;
  if k.voucher_id is not null then
    select v.code into v_voucher from public.vouchers v where v.id = k.voucher_id;
    if new.voucher_code is distinct from v_voucher then
      raise exception 'KODE_KAMPANYE: Kode % harus memakai voucher %', k.code, v_voucher using errcode = '23514';
    end if;
  elsif new.voucher_code is not null then
    raise exception 'KODE_KAMPANYE: Kode promo % tidak bisa digabung dengan voucher', k.code using errcode = '23514';
  end if;
  if k.max_uses is not null then
    v_used := public.campaign_code_used(k.code);
    if v_used >= k.max_uses then
      raise exception 'KODE_KAMPANYE: Kode % sudah mencapai batas pemakaian (% kali)', k.code, k.max_uses
        using errcode = 'P0001';
    end if;
  end if;
  return new;
end $$;
revoke all on function public.guard_campaign_code_use() from public, anon, authenticated, service_role;
drop trigger if exists c05_sale_campaign_code on public.sales;
create trigger c05_sale_campaign_code before insert or update of campaign_code, voucher_code on public.sales
  for each row execute function public.guard_campaign_code_use();
drop trigger if exists c05_invoice_campaign_code on public.invoices;
create trigger c05_invoice_campaign_code before insert or update of campaign_code, voucher_code on public.invoices
  for each row execute function public.guard_campaign_code_use();

-- Authoritative cap check at payment finalization (same transaction as the finalizer).
create or replace function public.guard_campaign_code_finalize() returns trigger
language plpgsql security definer set search_path = '' as $$
declare k public.campaign_codes%rowtype;
begin
  if new.campaign_code is null or old.payments_finalized_at is not null or new.payments_finalized_at is null then
    return new;
  end if;
  select * into k from public.campaign_codes c where c.code = new.campaign_code for update;
  if found and k.max_uses is not null and public.campaign_code_used(k.code) >= k.max_uses then
    raise exception 'KODE_KAMPANYE: Kode % sudah mencapai batas pemakaian (% kali)', k.code, k.max_uses
      using errcode = 'P0001';
  end if;
  return new;
end $$;
revoke all on function public.guard_campaign_code_finalize() from public, anon, authenticated, service_role;
drop trigger if exists c05_sale_campaign_code_finalize on public.sales;
create trigger c05_sale_campaign_code_finalize before update of payments_finalized_at on public.sales
  for each row execute function public.guard_campaign_code_finalize();

-- Usage per code for the manager screen (counts only; documents stay under their own RLS).
create or replace function public.campaign_code_usage()
returns table(code text, used bigint)
language plpgsql stable security definer set search_path = '' as $$
begin
  if not exists (select 1 from public.profiles p where p.id = (select auth.uid())
                 and p.is_active and p.role in ('OWNER','ADMIN')) then
    raise exception 'Akses ditolak' using errcode = '42501';
  end if;
  return query
    select c.code::text, public.campaign_code_used(c.code)
    from public.campaign_codes c order by c.code;
end $$;
revoke all on function public.campaign_code_usage() from public, anon, service_role;
grant execute on function public.campaign_code_usage() to authenticated;

-- Clinic posting stores the code inside its own atomic invoice insert (single, counted anchor;
-- split and DEMO posting call this core with the same p_invoice JSON).
do $patch$
declare
  signature regprocedure := 'public.clinic_post_invoice(uuid,text,jsonb,jsonb)'::regprocedure;
  definition text := pg_get_functiondef(signature);
  cols_old text := 'paid_status, metode_bayar, paid_at, shift_id, voucher_code, salesperson_id, service_pricing_version';
  vals_old text := E'v_shift.id, v_voucher, v_salesperson_id, nullif(p_invoice->>''service_pricing_version'','''')::smallint';
begin
  if position('campaign_code' in definition) > 0 then
    return;                                        -- already applied (idempotent re-run)
  end if;
  if (length(definition) - length(replace(definition, cols_old, ''))) / length(cols_old) <> 1
     or (length(definition) - length(replace(definition, vals_old, ''))) / length(vals_old) <> 1 then
    raise exception 'C05_CLINIC_POST_DRIFT: clinic_post_invoice changed; review before release';
  end if;
  definition := replace(definition, cols_old, cols_old || ', campaign_code');
  definition := replace(definition, vals_old, vals_old || E', nullif(p_invoice->>''campaign_code'','''')');
  execute definition;
end
$patch$;

commit;
